function normalizeMode(value){return value==='candles'?'candles':'food';}
function normalizeLang(value){return value==='it'?'it':'en';}
function escapeAttr(s){return String(s).replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;');}
function productLink(mode='food'){
 try{const u=new URL(globalThis.COLAVA?.stripePaymentLinks?.[normalizeMode(mode)]||'');if(u.protocol==='https:'&&(['buy.stripe.com','checkout.stripe.com'].includes(u.hostname))){if(typeof location!=='undefined')for(const [k,v] of new URLSearchParams(location.search))if(['utm_source','utm_medium','utm_campaign','utm_content'].includes(k))u.searchParams.set(k,v);return u.href;}}catch{}return '';
}
